{"file_path":"src/formula.js","content":"import { parseAddress, cmpAddr, addrKey } from './address.js'

const OPS = ['<>', '<=', '>=', '^', '*', '/', '+', '-', '=', '<', '>', '(', ')', ',', ':']

function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else {
      const op = OPS.find((o) => src.startsWith(o, i))
      if (!op) return null
      toks.push({ k: 'op', v: op })
      i += op.length
    }
  }
  return toks
}

// Returns an AST, or { t: 'bad' } when the grammar rejects the text
// (or a range sits outside a function argument).
export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return { t: 'bad' }
  let p = 0
  let misplaced = false
  const fail = new Error('parse')
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v

  function comparison() {
    let l = additive()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { t: 'bin', op: '^', l, r: power() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw fail
    const tk = toks[p]
    if (tk.k === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.k === 'op' && tk.v === '(') {
      p++
      const e = comparison()
      if (!isOp(')')) throw fail
      p++
      return e.t === 'range' ? { t: 'paren', e } : e
    }
    if (tk.k !== 'word') throw fail
    p++
    if (isOp('(')) {
      p++
      const args = []
      if (!isOp(')')) {
        for (;;) {
          const a = comparison()
          args.push(a)
          if (isOp(',')) { p++; continue }
          break
        }
      }
      if (!isOp(')')) throw fail
      p++
      return { t: 'call', name: tk.v.toUpperCase(), args }
    }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') throw fail
      const w2 = toks[p++].v
      if (isOp('(')) throw fail
      return { t: 'range', a: parseAddress(tk.v), b: parseAddress(w2) }
    }
    const up = tk.v.toUpperCase()
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', a: parseAddress(tk.v) }
  }

  let ast
  try {
    ast = comparison()
    if (p !== toks.length) return { t: 'bad' }
  } catch (e) {
    if (e === fail) return { t: 'bad' }
    throw e
  }
  if (!rangesOk(ast, false)) misplaced = true
  if (misplaced) return { t: 'bad', refs: ast }
  return ast
}

function rangesOk(n, asArg) {
  switch (n.t) {
    case 'range': return asArg
    case 'bin': return rangesOk(n.l, false) && rangesOk(n.r, false)
    case 'un': return rangesOk(n.e, false)
    case 'paren': return false
    case 'call': return n.args.every((a) => rangesOk(a, true))
    default: return true
  }
}

export function collectDeps(ast) {
  const set = new Map()
  const add = (a) => { if (a) set.set(addrKey(a), a) }
  const walk = (n) => {
    switch (n.t) {
      case 'ref': add(n.a); break
      case 'range':
        if (n.a && n.b) {
          const c1 = Math.min(n.a.col, n.b.col), c2 = Math.max(n.a.col, n.b.col)
          const r1 = Math.min(n.a.row, n.b.row), r2 = Math.max(n.a.row, n.b.row)
          for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) add({ col: c, row: r })
        }
        break
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': case 'paren': walk(n.e); break
      case 'call': n.args.forEach(walk); break
      case 'bad': if (n.refs) walk(n.refs); break
    }
  }
  walk(ast)
  return [...set.values()].sort(cmpAddr)
}
"}

